            ((FakeOccProj)clone).u07 = context.Clone(this.u07)!;
            ((FakeOccProj)clone).u08 = context.Clone(this.u08)!;
            ((FakeOccProj)clone).u09 = context.Clone(this.u09)!;
            ((FakeOccProj)clone).u10 = context.Clone(this.u10)!;
            ((FakeOccProj)clone).u11 = context.Clone(this.u11)!;
        }

        public virtual void ReadWrite(GbxReaderWriter rw, int v = 0)
        {
            rw.Int32(ref this.u01);
            rw.Int32(ref this.u02);
            rw.Int32(ref this.u03);
            rw.Quat(ref this.u04);
            rw.Single(ref this.u05);
            rw.Single(ref this.u06);
            rw.Single(ref this.u07);
            rw.Single(ref this.u08);
            rw.Single(ref this.u09);
            rw.Single(ref this.u10);
            rw.Single(ref this.u11);
        }

        public virtual void Read(GbxReader r, int v = 0)
        {
            using var rw = new GbxReaderWriter(r);
            ReadWrite(rw, v);
        }

        public virtual void Write(GbxWriter w, int v = 0)
        {
            using var rw = new GbxReaderWriter(w);
            ReadWrite(rw, v);
        }
    }

    internal override IChunk? NewChunk(uint chunkId) => chunkId switch
    {
        0x090BB000 => new Chunk090BB000(),
        0x090BB002 => new Chunk090BB002(),
        _ => base.NewChunk(chunkId),
    };
}
